'use strict';
// Display names stay separate from stable saved race/theme identifiers.
const RACE_DISPLAY_NAMES={Terran:'Helion',Cathaar:'Velari',Xandathrii:'Nexari',Zikonian:'Kryth',Eitraides:'Auralis'};
const THEME_DISPLAY_NAMES={Neutral:'Vesper Command',Terran:'Helion Ascendancy',Cathaar:'Velari Ember',Xandathrii:'Nexari Swarm',Zikonian:'Kryth Frost',Eitraides:'Auralis Tide',LCARS:'Stellar Federation',Borg:'Assimilation Nexus',Stargate:'Gatebound Legacy',DoctorWho:'Temporal Voyager',Battlestar:'Colonial Vanguard'};
function renamedDisplayText(value){let result=String(value);for(const [oldName,name] of Object.entries({'Neutral sci-fi':'Vesper Command','Star Trek LCARS':'Stellar Federation','Star Trek Borg':'Assimilation Nexus','Battlestar Galactica':'Colonial Vanguard','Doctor Who':'Temporal Voyager',Stargate:'Gatebound Legacy',...RACE_DISPLAY_NAMES})){result=result.replace(new RegExp('\\b'+oldName+'\\b','g'),name).replace(new RegExp('\\b'+oldName.toUpperCase()+'\\b','g'),name.toUpperCase());}return result;}
function applyDisplayNames(root){if(root.nodeType===3){if(root.parentElement?.tagName==='OPTION'){applyDisplayNames(root.parentElement);return;}if(!root.parentElement?.closest('script,style,textarea,code,input')){const updated=renamedDisplayText(root.nodeValue);if(updated!==root.nodeValue)root.nodeValue=updated;}return;}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1){if(root.tagName==='OPTION'){if(!root.hasAttribute('value'))root.setAttribute('value',root.value);const key=root.value,theme=['portalTheme','profileTheme','skinRaceSelect'].includes(root.parentElement?.id),label=theme?THEME_DISPLAY_NAMES[key]:RACE_DISPLAY_NAMES[key];if(label&&root.textContent!==label)root.textContent=label;return;}if(root.matches('script,style,textarea,code,input'))return;for(const attr of ['alt','title','aria-label'])if(root.hasAttribute(attr)){const old=root.getAttribute(attr),updated=renamedDisplayText(old);if(old!==updated)root.setAttribute(attr,updated);}}for(const child of root.childNodes)applyDisplayNames(child);}
function startDisplayNames(){applyDisplayNames(document.body);new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')applyDisplayNames(record.target);else for(const node of record.addedNodes)applyDisplayNames(node);}}).observe(document.body,{childList:true,subtree:true,characterData:true});document.title=renamedDisplayText(document.title);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startDisplayNames);else startDisplayNames();
